            orow.append(marks)
        res.append(orow)
    return res

def hyps(marks):
    h={}
    cols={}
    rowsd={}
    for i,j in marks:
        cols.setdefault(j,[]).append(i)
        rowsd.setdefault(i,[]).append(j)
    vpairs=[(i1,i2,j) for j,ii in cols.items() for a,i1 in enumerate(ii) for i2 in ii[a+1:]]
    hpairs=[(j1,j2,i) for i,jj in rowsd.items() for a,j1 in enumerate(jj) for j2 in jj[a+1:]]
    h['n2']=len(marks)==2
    h['vcol']=any(len(v)>=2 for v in cols.values())
    h['hrow']=any(len(v)>=2 for v in rowsd.values())
    h['v_nonadj']=any(abs(a-b)>1 for a,b,_ in vpairs)
    h['v_adj']=any(abs(a-b)==1 for a,b,_ in vpairs)
    h['v_dist2']=any(abs(a-b)==2 for a,b,_ in vpairs)
    h['diag']=any(abs(i1-i2)==abs(j1-j2) for i1,j1 in marks for i2,j2 in marks if (i1,j1)!=(i2,j2))
    return h

