    (a,b)=ms
    vert = a[1]==b[1]; horiz=a[0]==b[0]
    f['vert']=vert; f['horiz']=horiz; f['unal']=not vert and not horiz
    d=abs(a[0]-b[0])+abs(a[1]-b[1])
    f['gap0']=d==1; f['dist_ge2']=d>=2
    f['vgap']=vert and d>=2
    f['hgap']=horiz and d>=2
    rs=abs(a[0]-b[0])+1; cs=abs(a[1]-b[1])+1
    f['span_half']= (vert and rs*2>rh) or (horiz and cs*2>rw) or (unal and (rs*2>rh or cs*2>rw))
    f['span_half_strict']= (vert and rs*2>rh) or (horiz and cs*2>rw)
    f['col_edge']= any(j in (0,rw-1) for i,j in ms)
    f['row_edge']= any(i in (0,rh-1) for i,j in ms)
    f['same_col_last']= vert and a[1]==rw-1
    f['same_row_last']= horiz and a[0]==rh-1
    f['centered']= vert and min(a[0],b[0])<= (rh-1)/2 <= max(a[0],b[0]) and a[1]==(rw-1)//2
    return f

